async function request(url,options={}){const r=await fetch(url,{...options,credentials:'same-origin'});const data=await r.json();if(!r.ok){if(r.status===401&&S){S=null;render()}throw Object.assign(Error(data.error||'Permintaan gagal.'),{status:r.status,code:data.code,duplicates:data.duplicates})}return data}
