function installDateControls(){root.querySelectorAll('input[type="date"]').forEach(input=>{if(input.parentElement.classList.contains('date-control'))return;const wrapper=document.createElement('span');wrapper.className='date-control';input.before(wrapper);wrapper.append(input);const display=document.createElement('span');display.className='date-display';display.setAttribute('aria-hidden','true');wrapper.append(display);input.addEventListener('input',updateDateControls);input.addEventListener('change',updateDateControls);input.addEventListener('click',()=>{if(!input.disabled&&!input.readOnly&&input.showPicker)try{input.showPicker()}catch{}});});updateDateControls();}
