 if(c.status==='cancelled'){const x=c.cancellation;return `<section class="receipt cancellation-panel"><h3>Pengajuan dibatalkan</h3><p>${esc(x?.reason||'Alasan tidak tercatat')}</p>${x?`<p class="small muted">${esc(formatDateTime(x.createdAt))} · ${esc(x.actorName)} (${esc(x.actor)})</p>`:''}<p class="help">Pengajuan ini tidak lagi mengurangi plafon. Rincian, lampiran, dan nomor Payment Request tetap tersimpan.</p>${c.paymentRequestNo?`<p>Payment Request No.: <strong>${esc(c.paymentRequestNo)}</strong></p>`:''}${isHR()&&c.paymentRequest&&c.paymentRequestNo?`<a href="/api/claims/${encodeURIComponent(c.id)}/report">Unduh Payment Request dibatalkan</a>`:''}${c.financeDispatch?'<p class="error">Pengajuan sebelumnya sudah dikirim ke Finance. Informasikan pembatalan kepada Finance agar tidak dibayar.</p>':''}</section>`;}
